/**
 * Optimized lookup set for O(1) pincode checking
 * Stored as string for consistency with form inputs
 */
let pincodeSet: Set<string> | null = null;

/**
 * Get the serviceable pincode set (lazy initialized)
 */
export function getServiceablePincodeSet(): Set<string> {
  if (!pincodeSet) {
    pincodeSet = new Set(SERVICEABLE_PINCODES.map((code) => code.toString()));
  }
  return pincodeSet;
}

/**
 * Check if a pincode is serviceable
 * @param pincode - The pincode to check (string or number)
 * @returns true if the pincode is in serviceable area
 */
export function isServiceableArea(pincode: string | number): boolean {
  const pincodeStr = pincode.toString().trim();
  if (!pincodeStr) return false;
  return getServiceablePincodeSet().has(pincodeStr);
}

/**
 * Validate pincode format and serviceability
 * @param pincode - The pincode to validate
 * @returns Object with validation result and error message if any
 */
export function validatePincode(pincode: string): {
  isValid: boolean;
  isServiceable: boolean;
  error?: string;
} {
  const trimmed = pincode.trim();

  // Check if empty
  if (!trimmed) {
    return { isValid: false, isServiceable: false, error: "PIN code is required" };
  }

  // Check if only digits
  if (!/^\d+$/.test(trimmed)) {
    return { isValid: false, isServiceable: false, error: "PIN code must contain only digits" };
  }

  // Check length (Indian pincodes are typically 6 digits)
  if (trimmed.length !== 6) {
    return { isValid: false, isServiceable: false, error: "PIN code must be 6 digits" };
  }

  const isServiceable = isServiceableArea(trimmed);

  return {
    isValid: true,
    isServiceable,
    error: isServiceable ? undefined : `Service not available in area ${trimmed} yet`,
  };
}

/**
 * Get statistics about serviceable areas
 */
export function getPincodeStats() {
  return {
    totalServiceablePincodes: SERVICEABLE_PINCODES.length,
    coverage: `${SERVICEABLE_PINCODES.length}+ serviceable areas across Tamil Nadu`,
  };
}
